#define INF 1000000000

/*
  Dial lock DP.

  We have N dials, initial string A, target string B.
  Rotating dial i left by x also affects i+1 and i+2 in the same direction
  depending on operation size:
    - rotate 1 dial: affects i
    - rotate 2 adjacent dials: affects i and i+1
    - rotate 3 adjacent dials: affects i, i+1, i+2
  Each single step of such a rotation costs 1.
  Right rotations are symmetric.

  Standard DP:
  Process left to right. State keeps current offsets on positions i and i+1
  caused by previous operations: dp[i][a][b], where
    a = accumulated shift on dial i
    b = accumulated shift on dial i+1
  Then choose amounts x,y,z of left rotations on groups of size 1,2,3
  starting at i so that dial i matches target.
  Equivalent right rotations are handled by considering both left and right
  needed amounts.

  Transition:
    current digit at i = (A[i] + a) % 10
    need left t = (B[i] - current + 10) % 10
    or right 10-t (implemented as left t-10 in signed sense via two cases)

  If net rotation applied at i by operations starting at i is s = x+y+z,
  then after fixing dial i:
    new offset for i+1 = (b + y + z) % 10
    new offset for i+2 = z % 10
  Cost added = |x|+|y|+|z| minimized under x,y,z each same sign as chosen direction
  and x+y+z = required amount modulo 10 with minimal exact nonnegative amount
  in that direction.

  For a chosen nonnegative amount t (left steps), distribute among x,y,z >= 0
  with x+y+z=t minimizing future dp; brute force over y,z (t<=9).
  Similarly for right amount r=10-t, treat as negative direction; equivalent
  offsets subtract. We use modulo arithmetic.
*/

static int dp[1005][10][10];
static char A[1005], B[1005];

static inline int min(int a, int b) { return a < b ? a : b; }

int main(void) {
    int N;
    while (scanf("%d", &N) == 1 && N) {
        scanf("%s %s", A, B);

        for (int i = 0; i <= N; i++)
            for (int a = 0; a < 10; a++)
                for (int b = 0; b < 10; b++)
                    dp[i][a][b] = INF;

        dp[0][0][0] = 0;

        for (int i = 0; i < N; i++) {
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    int curCost = dp[i][a][b];
                    if (curCost == INF) continue;

                    int curDigit = (A[i] - '0' + a) % 10;
                    int target = B[i] - '0';

                    /* Left rotation case */
                    int t = (target - curDigit + 10) % 10; /* 0..9 */
                    for (int y = 0; y <= t; y++) {
                        for (int z = 0; z <= t - y; z++) {
                            int x = t - y - z;
                            int na = (b + y + z) % 10;
                            int nb = z % 10;
                            int nc = curCost + x + y + z;
                            if (dp[i + 1][na][nb] > nc)
                                dp[i + 1][na][nb] = nc;
                        }
                    }

                    /* Right rotation case */
                    int r = (curDigit - target + 10) % 10; /* 0..9 */
                    for (int y = 0; y <= r; y++) {
                        for (int z = 0; z <= r - y; z++) {
                            int x = r - y - z;
                            int na = (b - y - z) % 10;
                            int nb = (-z) % 10;
                            if (na < 0) na += 10;
                            if (nb < 0) nb += 10;
                            int nc = curCost + x + y + z;
                            if (dp[i + 1][na][nb] > nc)
                                dp[i + 1][na][nb] = nc;
                        }
                    }
                }
            }
        }

        printf("%d\n", dp[N][0][0]);
    }
    return 0;
}

