def solve(targets):
    n = len(targets)
    if n == 0:
        print(0)
        return

    INF = float('inf')
    # prev_val ranges: with n dials of 0-9, and starting from 0, max deviation bounded
    # Let's use range -100 to 100

    # dp[v] = min cost where previous effective value is v
    # Start: previous = 0 (boundary)

    prev = {0: 0}

    for i in range(n):
        curr = {}
        t = targets[i]
        # possible effective values for dial i: t + 10*k
        for pv, pcost in prev.items():
            # try several multiples
            for k in range(-15, 16):
                ev = t + 10 * k
                cost = pcost + abs(ev - pv)
                if ev not in curr or curr[ev] > cost:
                    curr[ev] = cost
        prev = curr

    # Final boundary: effective value after last dial, next is 0
    ans = INF
    for pv, pcost in prev.items():
        ans = min(ans, pcost + abs(pv))  # boundary 0 at end

    print(ans)

