// Precompute distances from all states to target
const int STATES = 10000;
vector<int> dist;

int encode(int a, int b, int c, int d) {
    return a * 1000 + b * 100 + c * 10 + d;
}

void precompute(const string& target) {
    dist.assign(STATES, -1);
    queue<int> q;
    int t = encode(target[0]-'0', target[1]-'0', target[2]-'0', target[3]-'0');
    dist[t] = 0;
    q.push(t);

    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int d = dist[cur];
        int a = cur / 1000;
        int b = (cur / 100) % 10;
        int c = (cur / 10) % 10;
        int dgt = cur % 10;

        // All possible moves:
        // Rotate 1 dial: positions 0,1,2,3 individually
        // Rotate 2 adjacent: (0,1), (1,2), (2,3)
        // Rotate 3 adjacent: (0,1,2), (1,2,3)
        // Rotate all 4: (0,1,2,3)
        vector<vector<int>> moves = {
            {0}, {1}, {2}, {3},
            {0,1}, {1,2}, {2,3},
            {0,1,2}, {1,2,3},
            {0,1,2,3}
        };

        for (auto& m : moves) {
            for (int dir = -1; dir <= 1; dir += 2) {
                int na = a, nb = b, nc = c, nd = dgt;
                if (find(m.begin(), m.end(), 0) != m.end()) na = (a + dir + 10) % 10;
                if (find(m.begin(), m.end(), 1) != m.end()) nb = (b + dir + 10) % 10;
                if (find(m.begin(), m.end(), 2) != m.end()) nc = (c + dir + 10) % 10;
                if (find(m.begin(), m.end(), 3) != m.end()) nd = (dgt + dir + 10) % 10;
                int nxt = encode(na, nb, nc, nd);
                if (dist[nxt] == -1) {
                    dist[nxt] = d + 1;
                    q.push(nxt);
                }
            }
        }
    }
}

