/*
We model the classic "vertical dial lock" problem.

State:
- There are n dials, current string s, target string t.
- A move chooses a position i and rotates dials i..n-1 by +1 or -1 (mod 10).
- We need minimum number of single-step rotations.

DP:
Process from left to right.
Let dp[i][r] = minimum moves after fixing first i dials,
where r is the accumulated rotation (mod 10) applied to dial i from previous moves.

At position i:
current digit becomes (s[i] + r) % 10.
To match t[i], we can:
1) rotate upward by u = (t[i] - cur + 10) % 10
   This also affects later dials, so next remainder becomes (r + u) % 10, cost +u.
2) rotate downward by d = (cur - t[i] + 10) % 10
   This does not change stored remainder for later in this left-to-right formulation,
   because downward on suffix is equivalent to reducing current only from perspective
   of current fixed dial while future accumulated upward remainder stays r.
   Cost +d, next remainder r.

This is the standard DP for BOJ 2494-like lock problem.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n;
        if (!(cin >> n)) return 0;
        if (n == 0) break;

        string s, t;
        cin >> s >> t;

        const int INF = 1e9;
        vector<vector<int>> dp(n + 1, vector<int>(10, INF));
        dp[0][0] = 0;

        for (int i = 0; i < n; ++i) {
            int a = s[i] - '0';
            int b = t[i] - '0';

            for (int r = 0; r < 10; ++r) {
                if (dp[i][r] == INF) continue;

                int cur = (a + r) % 10;

                int up = (b - cur + 10) % 10;
                dp[i + 1][(r + up) % 10] = min(dp[i + 1][(r + up) % 10], dp[i][r] + up);

                int down = (cur - b + 10) % 10;
                dp[i + 1][r] = min(dp[i + 1][r], dp[i][r] + down);
            }
        }

        int ans = *min_element(dp[n].begin(), dp[n].end());
        cout << ans << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class DialLock {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int n = sc.nextInt();
            if (n == 0) break;

            int[] current = new int[n];
            int[] target = new int[n];

            for (int i = 0; i < n; i++) {
                current[i] = sc.nextInt();
            }
            for (int i = 0; i < n; i++) {
                target[i] = sc.nextInt();
            }

            // dp[i][j] = min rotations for first i dials with j rotations carried to next dial
            // j ranges from -9 to 9, offset by 9 for indexing
            int offset = 9;
            int range = 19;
            int INF = 1_000_000;
            int[][] dp = new int[n + 1][range];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j < range; j++) {
                    dp[i][j] = INF;
                }
            }
            dp[0][offset] = 0; // no carry initially

            for (int i = 0; i < n; i++) {
                for (int carry = -9; carry <= 9; carry++) {
                    int idx = carry + offset;
                    if (dp[i][idx] == INF) continue;

                    int diff = (target[i] - current[i] - carry) % 10;
                    if (diff < 0) diff += 10;

                    // Try rotating up (diff times up)
                    int up = diff;
                    int newCarryUp = carry + up;
                    int idxUp = newCarryUp + offset;
                    if (idxUp >= 0 && idxUp < range) {
                        dp[i + 1][idxUp] = Math.min(dp[i + 1][idxUp], dp[i][idx] + up);
                    }

                    // Try rotating down (10 - diff times down)
                    int down = 10 - diff;
                    int newCarryDown = carry - down;
                    int idxDown = newCarryDown + offset;
                    if (idxDown >= 0 && idxDown < range) {
                        dp[i + 1][idxDown] = Math.min(dp[i + 1][idxDown], dp[i][idx] + down);
                    }
                }
            }

            int answer = INF;
            for (int carry = -9; carry <= 9; carry++) {
                answer = Math.min(answer, dp[n][carry + offset]);
            }
            System.out.println(answer);
        }
        sc.close();
    }
}

