public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int[] ini = new int[n], tgt = new int[n];
            for (int i = 0; i < n; i++) ini[i] = sc.nextInt();
            for (int i = 0; i < n; i++) tgt[i] = sc.nextInt();
            int[] d = new int[n];
            for (int i = 0; i < n; i++) d[i] = ((tgt[i] - ini[i]) % 10 + 10) % 10;
            // DP
            int RANGE = 50;
            int INF = Integer.MAX_VALUE/2;
            int[][] dp = new int[n+1][2*RANGE+1];
            for (int[] row : dp) Arrays.fill(row, INF);
            dp[0][RANGE] = 0; // v[0]=0, offset by RANGE
            for (int i = 0; i < n; i++) {
                for (int prev = 0; prev <= 2*RANGE; prev++) {
                    if (dp[i][prev] == INF) continue;
                    int pv = prev - RANGE;
                    for (int k = -5; k <= 5; k++) {
                        int cv = d[i] + 10*k;
                        int ci = cv + RANGE;
                        if (ci < 0 || ci > 2*RANGE) continue;
                        dp[i+1][ci] = Math.min(dp[i+1][ci], dp[i][prev] + Math.abs(cv - pv));
                    }
                }
            }
            System.out.println(dp[n][RANGE]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            String start = fs.next();
            String target = fs.next();

            int[][] dp = new int[n + 1][10];
            for (int i = 0; i <= n; i++) Arrays.fill(dp[i], INF);
            dp[0][0] = 0;

            for (int i = 0; i < n; i++) {
                int s = start.charAt(i) - '0';
                int t = target.charAt(i) - '0';

                for (int carry = 0; carry < 10; carry++) {
                    if (dp[i][carry] == INF) continue;

                    int cur = (s + carry) % 10;

                    // Rotate up (clockwise) so current digit becomes target
                    int up = (t - cur + 10) % 10;
                    int nextCarryUp = (carry + up) % 10;
                    dp[i + 1][nextCarryUp] = Math.min(dp[i + 1][nextCarryUp], dp[i][carry] + up);

                    // Rotate down (counterclockwise) only current dial
                    int down = (cur - t + 10) % 10;
                    dp[i + 1][carry] = Math.min(dp[i + 1][carry], dp[i][carry] + down);
                }
            }

            int ans = INF;
            for (int x = 0; x < 10; x++) ans = Math.min(ans, dp[n][x]);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new EOFException();
            return Integer.parseInt(s);
        }
    }
